"""Read only timing evidence generated by the current Gowin invocation."""
import html
import re

def current_report(folder, lower_bound):
    candidates=[folder/n for n in ('a745.tr','a745_tr_content.html')]
    candidates=[p for p in candidates if p.is_file() and p.stat().st_mtime>=lower_bound]
    if not candidates:
        return None, ''
    path=max(candidates,key=lambda p:p.stat().st_mtime)
    text=path.read_text(encoding='utf-8',errors='replace')
    if path.suffix=='.html':
        text=re.sub(r'(?is)<style.*?</style>|<script.*?</script>','',text)
        text=re.sub(r'(?is)\s*</t[dh]>\s*','\t',text)
        text=re.sub(r'(?is)</(?:tr|h[1-6]|p|div|table)>','\n',text)
        text=html.unescape(re.sub(r'(?is)<[^>]+>','',text))
        text='\n'.join(line.strip() for line in text.splitlines() if line.strip())
        headings={'Timing Messages':'1. Timing Message','Timing Summaries':'2. Timing Summaries',
          'STA Tool Run Summary:':'2.1 STA Tool Run Summary','Clock Summary:':'2.2 Clock Summary',
          'Max Frequency Summary:':'2.3 Max Frequency Summary','Total Negative Slack Summary:':'2.4 Total Negative Slack Summary',
          'Timing Details':'3. Timing Details','Path Slacks Table:':'3.1 Path Slacks Table',
          'Setup Paths Table':'3.1.1 Setup Paths Table','Hold Paths Table':'3.1.2 Hold Paths Table',
          'Recovery Paths Table':'3.1.3 Recovery Paths Table','Removal Paths Table':'3.1.4 Removal Paths Table',
          'Minimum Pulse Width Table:':'3.2 Minimum Pulse Width Table',
          'Timing Report By Analysis Type:':'3.3 Timing Report By Analysis Type',
          'High Fanout Nets Report:':'3.4 High Fanout Nets Report','Route Congestions Report:':'3.5 Route Congestions Report',
          'Timing Constraints Report:':'3.6 Timing Constraints Report'}
        text='\n'.join(headings.get(line,line) for line in text.splitlines())
        text=re.sub(r'\t(Setup|Hold|Recovery|Removal)\t',lambda m:'\t'+m[1].lower()+'\t',text)
    return path,text+'\n'
